`timescale 10ps/10ps
module IKA32010_tb;

reg             EMUCLK = 1'b1;
reg             RS_n = 1'b1;
reg             INT_n = 1'b1;

always #1 EMUCLK = ~EMUCLK;

reg     [1:0]   divider = 2'd0;
always @(posedge EMUCLK) divider <= divider + 2'd1;
wire            cen_n = ~(divider == 2'd3);
wire            refclk = ~divider[1];

initial begin
    #30 RS_n <= 1'b0;
    #100 RS_n <= 1'b1;

    #200 RS_n <= 1'b0;
    #120 RS_n <= 1'b1;

    #2420 INT_n <= 1'b0;
    #63 INT_n <= 1'b1;
end

wire            MEN_n, DEN_n, WE_n;
wire    [11:0]  ADDR;
wire    [15:0]  RDBUS, WRBUS;

IKA32010 main (
    .i_EMUCLK               (EMUCLK                     ),
    .i_CLKIN_PCEN           (~cen_n                     ),

    .o_CLKOUT               (                           ),
    .o_CLKOUT_PCEN          (                           ),
    .o_CLKOUT_NCEN          (                           ),

    .i_RS_n                 (RS_n                       ),

    .o_MEN_n                (MEN_n                      ),
    .o_DEN_n                (DEN_n                      ),
    .o_WE_n                 (WE_n                       ),

    .o_AOUT                 (ADDR                       ),
    .i_DIN                  (RDBUS                      ),
    .o_DOUT                 (WRBUS                      ),
    .o_DOUT_OE              (                           ),

    .i_BIO_n                (1'b1                       ),
    .i_INT_n                (INT_n                      )
);



reg     [15:0]  addrlatch;
always @(posedge EMUCLK) if(!WE_n && ADDR[2:0] == 3'd0) addrlatch <= WRBUS;


reg     [7:0]   m68kram_buf[0:16383];
reg     [15:0]  m68kram[0:8191];
integer i;
initial begin
    $readmemh("D:/PROCESSOR/IKA32010/IKA32010/rom/68k.txt", m68kram_buf);

    for(i=0; i<8192; i=i+1) begin
        m68kram[i] = {m68kram_buf[2*i], m68kram_buf[2*i+1]};
    end
end



assign  RDBUS = (DEN_n) ? 16'hZZZZ : m68kram[addrlatch[12:0]];





reg     [7:0]   dsp_hi[0:2047];
reg     [7:0]   dsp_lo[0:2047];
assign  RDBUS = (MEN_n) ? 16'hZZZZ : {dsp_hi[ADDR], dsp_lo[ADDR]};
initial begin
    $readmemh("D:/PROCESSOR/IKA32010/IKA32010/rom/dsp_hi.txt", dsp_hi);
    $readmemh("D:/PROCESSOR/IKA32010/IKA32010/rom/dsp_lo.txt", dsp_lo);
end








endmodule

module IKA32010 (
    //chip clock
    input   wire            i_EMUCLK, //emulator master clock
    input   wire            i_CLKIN_PCEN, //CLKIN positive edge enable

    //clock out
    output  wire            o_CLKOUT,
    output  wire            o_CLKOUT_PCEN,
    output  wire            o_CLKOUT_NCEN,

    //chip reset
    input   wire            i_RS_n,

    //bus control
    output  reg             o_MEN_n, //external instruction read
    output  reg             o_DEN_n, //IN instruction
    output  reg             o_WE_n, //OUT instruction

    output  wire    [11:0]  o_AOUT,
    input   wire    [15:0]  i_DIN,
    output  reg     [15:0]  o_DOUT,
    output  reg             o_DOUT_OE,

    //flag
    input   wire            i_BIO_n,

    //interrupt
    input   wire            i_INT_n
);


//debug output
`define IKA32010_DISASSEMBLY
`define IKA32010_DISASSEMBLY_SHOWID
`define IKA32010_DEVICE_ID "ikakawa"
`ifdef IKA32010_DISASSEMBLY
`include "IKA32010_disasm.sv"
`endif

//include mnemonic list
`include "IKA32010_mnemonics.sv"


///////////////////////////////////////////////////////////
//////  Clock
////

//master cycle counter
reg     [1:0]   cyclecntr;
always @(posedge i_EMUCLK) if(i_CLKIN_PCEN) begin
    if(!i_RS_n) cyclecntr <= 2'd0;
    else cyclecntr <= (cyclecntr == 2'd3) ? 2'd0 : cyclecntr + 2'd1;
end

//divided clock
assign  o_CLKOUT = cyclecntr[1];
assign  o_CLKOUT_NCEN = (cyclecntr == 2'd3) & i_CLKIN_PCEN;
assign  o_CLKOUT_PCEN = (cyclecntr == 2'd1) & i_CLKIN_PCEN;

wire            cyc_ncen = o_CLKOUT_NCEN;
wire            cyc_pcen = o_CLKOUT_PCEN;



///////////////////////////////////////////////////////////
//////  I/O status pin
////

//sampled at every positive edge?
reg             bio_n;
always @(posedge i_EMUCLK) if(cyc_pcen) begin
    bio_n <= i_BIO_n;
end



///////////////////////////////////////////////////////////
//////  Global write bus
////

reg     [15:0]  reg_wrbus;



///////////////////////////////////////////////////////////
//////  Opcode register
////

reg     [15:0]  if_opcodereg;
reg             if_opcodereg_force_iack;



///////////////////////////////////////////////////////////
//////  Program counter
////

reg     [11:0]  if_pc; //program counter
reg     [2:0]   if_pc_modesel;
wire    [11:0]  if_pc_next = (if_pc == 12'hFFF) ? 12'd000 : if_pc + 12'h001;

always @(posedge i_EMUCLK) begin
    if(!i_RS_n) if_pc <= 12'h000;
    else begin if(cyc_ncen) begin
        case(if_pc_modesel)
            PC_HOLD           : if_pc <= if_pc;
            PC_INCREASE       : if_pc <= if_pc_next;
            PC_LOAD_IMMEDIATE : if_pc <= i_DIN[11:0];
            PC_LOAD_INTERRUPT : if_pc <= 12'h002;
            PC_LOAD_WRBUS     : if_pc <= reg_wrbus[11:0];
            PC_RESET          : if_pc <= 12'h000;
            default           : if_pc <= if_pc;
        endcase
    end end
end



///////////////////////////////////////////////////////////
//////  Internal write bus control

module IKA32010_multiplier (
    input   wire            i_EMUCLK,
    input   wire            i_RST_n,

    input   wire            i_MUL_EN,

    input   wire    [15:0]  i_OP0,
    input   wire    [15:0]  i_OP1,
    output  wire    [31:0]  o_P
);

//Quartus(DE10-nano) and Vivado(Zybo-Z20) will synthesis this well using a DSP block

//multiplier
reg signed  [15:0]  op0_latch, op1_latch;
reg signed  [31:0]  result;
always @(posedge i_EMUCLK) begin
    if(!i_RST_n) begin
        op0_latch <= 16'sh0000;
        op1_latch <= 16'sh0000;
        result <= 32'sh0000_0000;
    end
    else begin
        if(i_MUL_EN) begin
            op0_latch <= signed'(i_OP0);
            op1_latch <= signed'(i_OP1);
            result <= op0_latch * op1_latch;
        end
    end
end

assign  o_P = unsigned'(result);

endmodule

